            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w
                            and grid[ny][nx] == 0
                            and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            components.append(comp)

    out = [row[:] for row in grid]
    if len(components) >= 2:
        smallest = min(range(len(components)), key=lambda i: len(components[i]))
        largest = max(range(len(components)), key=lambda i: len(components[i]))
        for r, c in components[smallest]:
            out[r][c] = 7
        if largest != smallest:
            for r, c in components[largest]:
                out[r][c] = 8

    return out
